+static nstime_t
+gps_to_utctime(const guint32 gpstime)
+{
+	nstime_t utctime;
+	utctime.secs = (guint64)gpstime;
+	utctime.secs += 315964800; /* difference between Unix epoch and GPS epoch */
+	utctime.secs -= 18; /* leap seconds valid after 2017-01-01 */
+	utctime.nsecs = 0;
+	return utctime;
+}
